return [
    'star-method' => ['article', 'behavioral', 1,
        'fr' => ['La méthode STAR pour les questions comportementales', 'Structurer un exemple vécu en quatre temps pour une réponse claire et convaincante.',
            "Les questions comportementales commencent souvent par « Racontez une situation où… ». Le recruteur cherche des preuves de ce que vous avez réellement fait.\n\nSituation : posez le contexte en deux phrases. Où étiez-vous, quel était l'enjeu ?\n\nTâche : précisez votre rôle et l'objectif à atteindre.\n\nActions : c'est le cœur de la réponse. Décrivez ce que vous avez fait personnellement, en utilisant « je », et expliquez pourquoi.\n\nRésultats : terminez par un résultat concret, chiffré si possible, et ce que vous en avez retenu.\n\nConseil : préparez cinq ou six histoires polyvalentes (conflit, échec, réussite, pression, initiative, travail en équipe) que vous pourrez adapter à de nombreuses questions."],
        'en' => ['The STAR method for behavioural questions', 'Structure a real example in four steps for a clear, convincing answer.',
            "Behavioural questions often start with \"Tell me about a time when...\". The interviewer is looking for evidence of what you actually did.\n\nSituation: set the context in two sentences. Where were you and what was at stake?\n\nTask: state your role and the goal.\n\nActions: the core of the answer. Describe what you personally did, using \"I\", and explain why.\n\nResults: end with a concrete, ideally quantified outcome and what you learned.\n\nTip: prepare five or six versatile stories (conflict, failure, success, pressure, initiative, teamwork) that you can adapt to many questions."]],
    'salary-preparation' => ['article', 'negotiation', 2,
        'fr' => ['Préparer la négociation salariale', 'Arriver avec une fourchette argumentée et une vision globale du package.',
            "Renseignez-vous avant l'entretien : études de rémunération du secteur, offres comparables, échanges avec votre réseau.\n\nDéfinissez trois chiffres : votre objectif, votre fourchette annoncée et votre seuil minimal, que vous gardez pour vous.\n\nArgumentez par la valeur : expérience, compétences rares, responsabilités du poste, résultats obtenus.\n\nPensez au package global : part variable, avantages, télétravail, formation, date de revue salariale.\n\nRestez courtois et factuel. Demander un délai de réflexion avant d'accepter une offre est une pratique normale."],
        'en' => ['Preparing for salary negotiation', 'Come with a reasoned range and a view of the whole package.',
            "Do your research before the interview: sector salary surveys, comparable job offers and conversations with your network.\n\nSet three numbers: your target, the range you will state and your walk-away point, which you keep to yourself.\n\nArgue with value: experience, rare skills, the role's responsibilities and results achieved.\n\nConsider the whole package: bonus, benefits, remote work, training and the date of the next salary review.\n\nStay courteous and factual. Asking for time to think before accepting an offer is normal practice."]],
    'competency-interviews' => ['article', 'international', 3,
        'fr' => ['Réussir un entretien par compétences en organisation internationale', 'Comprendre les référentiels de compétences et y répondre avec des exemples.',
            "Les organisations internationales évaluent souvent des compétences définies dans un référentiel : professionnalisme, intégrité, respect de la diversité, orientation client, planification, redevabilité, travail d'équipe.\n\nLisez attentivement l'avis de vacance : les compétences citées sont généralement celles qui seront évaluées.\n\nPour chaque compétence, préparez un exemple STAR récent et précis. Les jurys apprécient les résultats mesurables et la mention des leçons tirées.\n\nMontrez votre compréhension du mandat de l'organisation et votre aisance dans un environnement multiculturel.\n\nRestez factuel : évitez les généralisations sur les cultures et privilégiez des situations vécues."],
        'en' => ['Succeeding in a competency based interview with an international organisation', 'Understand competency frameworks and answer them with examples.',
            "International organisations often assess competencies defined in a framework: professionalism, integrity, respect for diversity, client orientation, planning, accountability and teamwork.\n\nRead the vacancy announcement carefully: the competencies it lists are usually the ones assessed.\n\nFor each competency, prepare a recent, specific STAR example. Panels value measurable results and lessons learned.\n\nShow that you understand the organisation's mandate and are comfortable in a multicultural environment.\n\nStay factual: avoid generalisations about cultures and use real situations."]],
    'technical-interviews' => ['article', 'technical', 4,
        'fr' => ['Aborder une question technique', 'Penser à voix haute, structurer, justifier ses choix.',
            "Reformulez la question pour vérifier votre compréhension et posez des questions sur le contexte.\n\nAnnoncez votre démarche avant d'entrer dans le détail : étapes, hypothèses, outils.\n\nJustifiez vos choix et mentionnez les compromis : performance, sécurité, coût, maintenabilité.\n\nSi vous ne savez pas, dites-le et expliquez comment vous trouveriez la réponse. L'honnêteté est mieux perçue qu'une réponse inventée.\n\nTerminez par une vérification : comment testeriez-vous ou valideriez-vous votre solution ?"],
        'en' => ['Tackling a technical question', 'Think aloud, structure, justify your choices.',
            "Rephrase the question to check your understanding and ask about the context.\n\nOutline your approach before going into detail: steps, assumptions, tools.\n\nJustify your choices and mention trade-offs: performance, security, cost, maintainability.\n\nIf you do not know, say so and explain how you would find out. Honesty is better received than an invented answer.\n\nEnd with verification: how would you test or validate your solution?"]],
    'stress-management' => ['tip', null, 5,
        'fr' => ['Gérer le stress le jour de l\'entretien', 'Quelques habitudes simples qui aident à rester clair.',
            "Préparez la logistique la veille : trajet, documents, connexion pour un entretien à distance.\n\nEntraînez-vous à voix haute sur vos exemples clés plutôt que de les relire.\n\nAvant de répondre, prenez deux secondes pour structurer votre idée. Un silence court est normal.\n\nSi vous perdez le fil, résumez ce que vous avez dit et reprenez.\n\nAprès l'entretien, notez les questions posées et ce que vous amélioreriez : c'est la meilleure préparation pour la prochaine fois."],
        'en' => ['Managing stress on interview day', 'A few simple habits to stay clear headed.',
